 3 │ Kódok  

 3.1 │ requirements.txt


fastapi==0.111.0
uvicorn==0.30.1


> A FastAPI tartalmazza a Pydanticot; extra LLMcsomag (pl. llama-cpp-python) a projekt igény szerint bővíthető.

 3.2 │ main.py  (backend – 100% komplett)  

python
"""Autonóm AI Tudásgyűjtő + Chat rendszer – FastAPI backend"""
from __future__ import annotations

import asyncio
import random
from datetime import datetime
from pathlib import Path
from typing import List

from fastapi import FastAPI, BackgroundTasks, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field

# --------------------------------------------------------------------- #
# FastAPI + CORS
# --------------------------------------------------------------------- #
app = FastAPI(title="Szuper AI Backend", version="1.0.0")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

# --------------------------------------------------------------------- #
# 1. ÁLLAPOTMODELLEK
# --------------------------------------------------------------------- #
class ValidationMetrics(BaseModel):
    accuracy: float = Field(0, ge=0, le=1)
    precision: float = Field(0, ge=0, le=1)
    recall: float = Field(0, ge=0, le=1)
    f1_score: float = Field(0, ge=0, le=1)


class ModelMetrics(BaseModel):
    train_loss: float = 1.0
    val_loss: float = 1.0
    val_accuracy: float = 0.0


class SystemState(BaseModel):
    collector_running: bool = False
    validator_running: bool = False
    trainer_running: bool = False
    docs_total: int = 0
    docs_valid: int = 0
    training_steps: int = 0
    validation_metrics: ValidationMetrics = ValidationMetrics()
    model_metrics: ModelMetrics = ModelMetrics()


STATE = SystemState()
_state_lock = asyncio.Lock()
_LOGS: List[str] = []

def _log(msg: str) -> None:
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    _LOGS.append(f"[{ts}] {msg}")
    if len(_LOGS) > 1_000:
        _LOGS.pop(0)


# --------------------------------------------------------------------- #
# 2. HÁTTÉRFOLYAMATOK (mock implementáció – API-hívással replacelhető)
# --------------------------------------------------------------------- #
async def _collector() -> None:
    _log("Tudásgyűjtő | START")
    while STATE.collector_running:
        await asyncio.sleep(10)
        new_docs = random.randint(25, 75)
        async with _state_lock:
            STATE.docs_total += new_docs
        _log(f"Tudásgyűjtő | +{new_docs} doc (össz: {STATE.docs_total})")
    _log("Tudásgyűjtő | STOP")

async def _validator() -> None:
    _log("Validátor | START")
    while STATE.validator_running:
        await asyncio.sleep(12)
        async with _state_lock:
            pending = STATE.docs_total - STATE.docs_valid
            batch = min(pending, random.randint(15, 50))
            STATE.docs_valid += batch
            STATE.validation_metrics = ValidationMetrics(
                accuracy=round(random.uniform(0.9, 0.97), 3),
                precision=round(random.uniform(0.88, 0.95), 3),
                recall=round(random.uniform(0.86, 0.94), 3),
                f1_score=round(random.uniform(0.87, 0.95), 3),
            )
        _log(f"Validátor   | +{batch} doc OK (össz: {STATE.docs_valid})")
    _log("Validátor | STOP")

async def _trainer() -> None:
    _log("Tréner | START")
    while STATE.trainer_running:
        await asyncio.sleep(20)
        async with _state_lock:
            STATE.training_steps += 1
            # szimulált javuló metrikák
            STATE.model_metrics.train_loss = max(
                0.03, STATE.model_metrics.train_loss - random.uniform(0.02, 0.04)
            )
            STATE.model_metrics.val_loss = max(
                0.03, STATE.model_metrics.val_loss - random.uniform(0.015, 0.03)
            )
            STATE.model_metrics.val_accuracy = min(
                0.99, STATE.model_metrics.val_accuracy + random.uniform(0.015, 0.03)
            )
        _log(
            f"Tréner      | step {STATE.training_steps}  "
            f"val_loss={STATE.model_metrics.val_loss:.3f}"
        )
    _log("Tréner | STOP")

# --------------------------------------------------------------------- #
# 3. API – MODUL VEZÉRLÉS
# --------------------------------------------------------------------- #
class ToggleRequest(BaseModel):
    module: str
    state: bool

@app.post("/api/toggle")
async def toggle(req: ToggleRequest, bg: BackgroundTasks):
    mod = req.module.lower()
    if mod not in {"collector", "validator", "trainer"}:
        raise HTTPException(400, "Érvénytelen modulnév")
    async with _state_lock:
        setattr(STATE, f"{mod}_running", req.state)
    _log(f"Toggle      | {mod} → {'ON' if req.state else 'OFF'}")

    if req.state:          # indulás
        task_map = {
            "collector": _collector,
            "validator": _validator,
            "trainer": _trainer,
        }
        bg.add_task(task_map[mod])
    return {"ok": True}

@app.get("/api/status", response_model=SystemState)
async def status() -> SystemState:
    async with _state_lock:
        return STATE

@app.get("/api/logs")
async def logs():
    return {"logs": _LOGS[-200:]}   # utolsó 200 sor

# --------------------------------------------------------------------- #
# 4. CHAT ENDPOINT
# --------------------------------------------------------------------- #
class ChatRequest(BaseModel):
    message: str = Field(..., min_length=1, max_length=8_000)

class ChatResponse(BaseModel):
    response: str

# ↓ Itt cseréld ki valós LLM-hívásra (pl. llama-cpp, OpenAI, Cerebras stb.)
async def _generate_ai_response(prompt: str) -> str:
    await asyncio.sleep(0.5)                       # szimulált latencia
    canned = ["Érdekes kérdés!", "Dolgozom a válaszon…", "Persze, segítek!"]
    return random.choice(canned) + " [demo-mód]"

@app.post("/api/chat", response_model=ChatResponse)
async def chat(req: ChatRequest):
    reply = await _generate_ai_response(req.message)
    _log(f"Chat        | Q: {req.message[:60]}..  A: {reply[:60]}..")
    return {"response": reply}

# --------------------------------------------------------------------- #
# 5. STATIKUS FÁJLOK KISZOLGÁLÁSA
# --------------------------------------------------------------------- #
root = Path(__file__).parent.resolve()
app.mount("/", StaticFiles(directory=root, html=True), name="static")

# (Az index.html és chat.html a gyökérben van, így közvetlenül elérhető.)


