}

function setStatus(id, run){
  const el = document.getElementById(id+'-status');
  el.textContent = run ? 'Fut' : 'Leállítva';
  el.className = 'status ' + (run ? 'running' : 'stopped');
}

async function refresh(){
  const s = await api('/api/status');
  setStatus('collector', s.collector_running);
  setStatus('validator', s.validator_running);
  setStatus('trainer',  s.trainer_running);
  document.getElementById('docs-total').textContent = s.docs_total;
  document.getElementById('docs-valid').textContent = s.docs_valid;
  document.getElementById('train-steps').textContent = s.training_steps;
  document.getElementById('val-acc').textContent =
    (s.validation_metrics.accuracy*100).toFixed(1)+'%';
}

